, "issues": [{"section_id": "S_evaluation", "severity": "error", "paragraph_id": "S_evaluation_p1", "reason": "E00278의 Bound+Infer 합산(658.80+127.18=785.98s)이 전체 787.88s와 약 1.9s 차이가 있다는 한계가 명시되어 있음에도, 본문은 Bound 658.80s와 Infer 127.18s를 cudaHostRegister의 전체 시간 787.88s와 정합적으로 연결하지 않고 그대로 병기해 수치 정합성 설명이 부족하다.", "evidence_ids": ["E00278"]}, {"section_id": "S_evaluation", "severity": "error", "paragraph_id": "S_evaluation_p2", "reason": "E00292의 'No-Pin이 13초 빠름'은 구체적 테스트 조건(데이터 크기, 반복 횟수, 전체 실행 시간 대비 맥락)이 명시되지 않은 요약 수치인데, 본문은 이를 평균 처리 속도 차이의 확정적 비교처럼 서술해 근거의 한계를 반영하지 않았다.", "evidence_ids": ["E00292"]}, {"section_id": "S_evaluation", "severity": "error", "paragraph_id": "S_evaluation_p2", "reason": "E00295의 '약 1.4% 미세하게 낮게 측정될 수 있다'는 표현은 특정 조건에서의 가능성인지 일반적 경향인지 모호하고 근사치 표현인데, 본문은 이를 측정 결과의 단정적 서술로 바꿔 썼다.", "evidence_ids": ["E00295"]}, {"section_id": "S_evaluation", "severity": "error", "paragraph_id": "S_evaluation_p2", "reason": "E00303과 E00304는 H2D 복사 시간 영향 가능성 및 cudaMemcpyAsync 측정 결과가 빠르거나 느리게 바뀌어 확신할 수 없다는 해석·관측인데, 본문은 이를 평균 속도와 실시간 안정성의 불일치를 설명하는 확정적 인과처럼 연결해 근거의 해석 범위를 넘었다.", "evidence_ids": ["E00303", "E00304"]}, {"section_id": "S_evaluation", "severity": "error", "paragraph_id": "S_evaluation_p3", "reason": "E00306의 '마지막 측정에서 nopinned가 더 빠르게 나와 확신할 수 없게 되었다'는 정성적 관찰을 본문은 여러 번 측정 결과의 일관된 결론처럼 서술해 근거의 불확실성을 약화했다.", "evidence_ids": ["E00306"]}, {"section_id": "S_evaluation", "severity": "error", "paragraph_id": "S_evaluation_p3", "reason": "E00297은 DMA 셋업 오버헤드와 CPU 캐시 복사 이득에 대한 해석(문맥 근거 전용, 관측 결과로 쓰지 않음)인데, 본문은 이를 1회·누적 오버헤드 수치와 함께 사실 서술로 사용해 근거의 작성 역할과 충돌한다.", "evidence_ids": ["E00297"]}] 
